@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--bg:#090912;--ink:#f4f3f6;--muted:#a19daa;--line:rgba(255,255,255,.15);--pink:#ff4e91;--cyan:#62e8dd;--yellow:#f6cb74;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--ink);font-family:var(--sans)}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}.app-shell{position:relative;width:100%;height:100%;min-height:600px;overflow:hidden;background:#0a0a13}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(8,8,15,.9) 0%,rgba(8,8,15,.66) 35%,rgba(8,8,15,.08) 75%),linear-gradient(0deg,rgba(8,8,15,.84),transparent 42%,rgba(8,8,15,.25));z-index:1}.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:76px;padding:0 5.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.1);background:rgba(8,8,15,.35);backdrop-filter:blur(8px)}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);text-decoration:none;font-size:13px;font-weight:700;letter-spacing:.13em}.brand-mark{width:29px;height:29px;border:1px solid var(--pink);color:var(--pink);display:grid;place-items:center;font-size:18px;font-weight:600;transform:rotate(-8deg)}.brand-light{font-weight:400;color:#bbb6c3}.top-status,.wallet{font:10px var(--mono);letter-spacing:.09em;color:#d4d0da;display:flex;align-items:center;gap:9px}.live-dot{height:7px;width:7px;border-radius:50%;background:#7df0bc;box-shadow:0 0 11px #7df0bc;display:inline-block}.wallet{color:var(--yellow);font-size:15px;font-weight:500;gap:6px}.wallet-label{font-size:9px;color:#a8a3b2;margin-left:4px}.coin{font-family:var(--sans);font-weight:700}.screen{position:absolute;z-index:2;inset:76px 0 0}.welcome-screen{display:flex;align-items:center;padding:0 5.2%;gap:8%;}.welcome-copy{width:43%;max-width:530px;padding-bottom:38px}.eyebrow{font:10px var(--mono);letter-spacing:.16em;color:var(--cyan);margin:0 0 17px}.eyebrow-line{width:24px;height:1px;background:var(--cyan);display:inline-block;vertical-align:middle;margin-right:8px}.welcome-copy h1{font-size:clamp(54px,7vw,98px);line-height:.91;letter-spacing:-.075em;margin:0;font-weight:600}.welcome-copy h1 em,.garage-card h2 em{font-weight:400;color:var(--pink);font-style:normal}.intro{font-size:14px;line-height:1.75;color:#c0bbc8;max-width:390px;margin:25px 0 25px}.career-note{display:flex;gap:12px;align-items:center;border-left:1px solid var(--pink);padding:5px 0 5px 14px}.note-icon{font-size:21px;color:var(--pink)}.career-note b,.career-note small{display:block}.career-note b{font-size:12px;font-weight:600}.career-note small{font-size:10px;color:var(--muted);margin-top:4px}.style-picker{width:min(510px,47%);margin-left:auto;background:rgba(12,12,22,.86);border:1px solid rgba(255,255,255,.18);box-shadow:0 24px 80px #03030a8c;padding:25px 25px 20px;backdrop-filter:blur(16px)}.picker-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:17px}.picker-heading .eyebrow{margin-bottom:7px;font-size:9px}.picker-heading h2{font-size:21px;letter-spacing:-.04em;margin:0}.step-count{font:11px var(--mono);color:var(--pink)}.step-count i{font-style:normal;color:#77717f}.style-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.style-card{position:relative;text-align:left;background:#14141f;border:1px solid rgba(255,255,255,.11);padding:13px 11px 12px;min-height:155px;transition:.2s}.style-card:hover{background:#1b1a28;transform:translateY(-2px)}.style-card.selected{border-color:var(--pink);background:linear-gradient(145deg,rgba(255,78,145,.14),#14141f 67%)}.style-card.selected:after{content:'✓';position:absolute;right:8px;top:7px;color:var(--pink);font-size:12px}.instrument-icon{display:block;font-size:27px;height:39px;color:var(--pink);line-height:1}.flute-icon{color:var(--cyan)}.keys-icon{color:var(--yellow)}.style-name{display:block;font-size:14px;font-weight:600}.style-tag{display:block;font:8px var(--mono);letter-spacing:.12em;color:#a9a4b1;margin:4px 0 8px}.style-desc{display:block;min-height:26px;font-size:9px;color:#b9b5c0;line-height:1.4}.style-stat{display:block;height:2px;background:#373541;margin-top:8px}.style-stat i{display:block;height:100%;width:var(--stat);background:var(--pink)}.style-card:nth-child(2) .style-stat i{background:var(--cyan)}.style-card:nth-child(3) .style-stat i{background:var(--yellow)}.primary-button,.secondary-button{height:48px;border:0;background:var(--pink);color:#160b12;font:700 10px var(--mono);letter-spacing:.1em;display:flex;align-items:center;justify-content:space-between;padding:0 17px;transition:.2s}.primary-button:hover{background:#ff77aa;transform:translateY(-1px)}.primary-button span{font-size:17px}.style-picker>.primary-button{width:100%;margin-top:17px}.picker-foot{font:8px var(--mono);letter-spacing:.08em;color:#888391;margin:13px 0 0;text-align:center}.picker-foot kbd{border:1px solid #625e6b;padding:2px 4px;color:#d7d4dc;font:8px var(--mono);margin:0 3px}.welcome-footer{position:absolute;bottom:20px;left:5.2%;right:5.2%;display:flex;justify-content:space-between;color:#7e7988;font:8px var(--mono);letter-spacing:.11em}.corner-coordinate{position:absolute;z-index:2;bottom:24px;right:5.2%;font:8px/1.7 var(--mono);letter-spacing:.08em;color:#9b96a3;text-align:right}.corner-coordinate span{color:#d0cbd5}.game-screen{padding:24px 5.2% 20px;display:flex;flex-direction:column}.hidden{display:none!important}.battle-head{display:flex;align-items:center;gap:22px}.battle-title{flex:1}.battle-title .eyebrow{margin-bottom:5px;font-size:9px}.battle-title h2{font-size:24px;letter-spacing:-.04em;margin:0}.round-pill{border:1px solid rgba(255,255,255,.2);padding:9px 12px;font:9px var(--mono);letter-spacing:.09em;display:flex;gap:8px;align-items:center;color:#ddd9e2}.round-pill .live-dot{height:6px;width:6px}.icon-button{background:#171620;border:1px solid var(--line);height:34px;padding:0 11px;color:var(--cyan);font-size:15px}.icon-button span{font:8px var(--mono);letter-spacing:.08em;color:#bbb6c1;margin-left:5px}.combat-ui{display:flex;align-items:center;justify-content:space-between;width:min(760px,88%);margin:35px auto 0;gap:45px}.fighter-card{position:relative;width:280px;padding:14px 15px 13px;background:rgba(12,12,22,.77);border:1px solid rgba(255,255,255,.15);backdrop-filter:blur(8px);box-shadow:0 14px 34px #06060b55}.player-card{border-top:2px solid var(--cyan)}.rival-card{border-top:2px solid var(--pink)}.fighter-meta{display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spacing:.12em;color:#aaa5b3}.fighter-level{font-size:8px;color:#d1cdd7}.fighter-name{font-size:20px;font-weight:700;letter-spacing:-.04em;margin:6px 0 12px}.health-track{height:5px;background:#373541;overflow:hidden}.health-track i{height:100%;width:100%;display:block;background:var(--cyan);transition:width .35s ease}.rival-track i{background:var(--pink)}.health-caption{display:flex;justify-content:space-between;margin-top:7px;color:#a8a3af;font:8px var(--mono);letter-spacing:.08em}.health-caption b{color:#e6e2eb;font-weight:400}.fighter-badge{position:absolute;right:15px;top:34px;font-size:24px;color:var(--cyan);opacity:.72}.rival-badge{color:var(--pink)}.versus{font:700 13px var(--mono);color:#f2eff6;text-shadow:0 0 14px var(--pink)}.rhythm-panel{width:min(520px,75%);margin:30px auto 0;background:rgba(11,11,19,.78);border:1px solid rgba(255,255,255,.13);padding:13px 17px 10px;backdrop-filter:blur(6px)}.rhythm-label{font:9px var(--mono);letter-spacing:.12em;color:#c3becb;display:flex;align-items:center;gap:8px;margin-bottom:10px}.rhythm-label b{margin-left:auto;color:var(--cyan);font-weight:400}.beat-indicator{width:6px;height:6px;background:var(--cyan);border-radius:50%;box-shadow:0 0 10px var(--cyan)}.beat-track{height:13px;background:linear-gradient(90deg,#20202c,#171720);position:relative;overflow:hidden}.beat-fill{position:absolute;left:0;top:0;height:100%;width:0;background:linear-gradient(90deg,#3b79a5,#5fe9d7);opacity:.42}.beat-target{position:absolute;left:82%;height:100%;width:3px;background:var(--yellow);box-shadow:0 0 12px var(--yellow)}.beat-pulse{position:absolute;left:0;top:0;height:100%;width:14px;background:var(--cyan);box-shadow:0 0 15px var(--cyan);transform:translateX(-20px)}.beat-hint{display:flex;justify-content:space-between;color:#77727f;font:7px var(--mono);letter-spacing:.08em;margin-top:6px}.beat-hint span:nth-child(2){color:var(--yellow)}.beat-hint b{font-weight:400}.battle-bottom{display:grid;grid-template-columns:1fr 1.4fr 1fr;align-items:center;gap:25px;width:min(640px,85%);margin:22px auto 0}.combo-box,.score-box{display:flex;flex-direction:column}.score-box{text-align:right}.combo-label{font:8px var(--mono);letter-spacing:.12em;color:#9893a1}.combo-box>b,.score-box>b{font:24px var(--mono);letter-spacing:-.07em;margin:1px 0;color:#f3f0f7}.combo-box>b span{font-size:13px;color:var(--pink)}.combo-box small,.score-box small{font:7px var(--mono);color:#8f8998;letter-spacing:.06em}.attack-button{height:55px;position:relative;border:1px solid var(--cyan);background:rgba(35,145,140,.18);box-shadow:0 0 26px rgba(98,232,221,.12);display:flex;align-items:center;justify-content:center;gap:12px;transition:.1s}.attack-button:hover,.attack-button:active{background:rgba(98,232,221,.34);transform:scale(.985)}.attack-key{font:8px var(--mono);color:#b4f7ed;border:1px solid rgba(180,247,237,.4);padding:4px}.attack-text{font:700 12px var(--mono);letter-spacing:.15em;color:#e3fffb}.attack-arrow{position:absolute;right:12px;color:var(--cyan);font-size:16px}.game-footer{margin-top:auto;border-top:1px solid rgba(255,255,255,.13);padding-top:12px;display:flex;align-items:center;gap:18px;font:8px var(--mono);letter-spacing:.09em;color:#96919e}.text-button{background:none;border:0;color:#d6d2dc;font:8px var(--mono);letter-spacing:.09em;padding:5px 0}.text-button:hover{color:var(--cyan)}.text-button span{color:#898491;margin-left:7px}.exit-button{margin-left:auto;color:#8e8996}.overlay-modal{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:rgba(6,6,12,.69);backdrop-filter:blur(9px)}.modal-card{position:relative;width:min(410px,calc(100vw - 32px));padding:33px;background:#11111c;border:1px solid rgba(255,255,255,.19);box-shadow:0 24px 90px #000b}.result-card{text-align:center}.result-stamp{width:54px;height:54px;display:grid;place-items:center;margin:0 auto 17px;border:1px solid var(--cyan);border-radius:50%;color:var(--cyan);font-size:25px;box-shadow:0 0 25px #62e8dd24}.result-card .eyebrow{margin-bottom:9px}.result-card h2{font-size:31px;letter-spacing:-.06em;margin:0 0 7px}.result-card>p:not(.eyebrow){font-size:12px;color:#aaa5b3;margin:0}.reward-line{border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:23px 0 17px;padding:13px 0;display:flex;justify-content:space-between;align-items:center;font:9px var(--mono);letter-spacing:.1em;color:#aaa5b3}.reward-line b{color:var(--yellow);font-size:17px;letter-spacing:0}.result-actions{display:grid;gap:9px}.result-actions button{width:100%}.secondary-button{justify-content:center;background:#20202b;color:#e6e2ea;border:1px solid #44414e}.secondary-button:hover{background:#2d2c38}.garage-card{padding:34px}.garage-card .eyebrow{margin-bottom:9px}.garage-card h2{font-size:33px;line-height:1.02;letter-spacing:-.07em;margin:0}.garage-copy{font-size:12px;color:#aaa5b3;line-height:1.65;margin:15px 0 23px}.upgrade-row{display:flex;align-items:center;gap:12px;background:#1a1925;border:1px solid #373441;padding:12px;margin-bottom:12px}.upgrade-icon{width:36px;height:36px;display:grid;place-items:center;color:var(--yellow);background:#302a21;font-size:17px}.upgrade-info{flex:1}.upgrade-info b,.upgrade-info small{display:block}.upgrade-info b{font-size:11px}.upgrade-info small{font-size:9px;color:#9d98a5;margin-top:4px}.upgrade-price{font:11px var(--mono);color:var(--yellow)}.garage-card>.primary-button{width:100%}.garage-level{text-align:center;font:8px var(--mono);letter-spacing:.08em;color:#878291;margin:13px 0 0}.modal-close{position:absolute;right:14px;top:10px;border:0;background:none;color:#b9b4c1;font-size:24px}.toast{position:absolute;z-index:10;bottom:62px;left:50%;transform:translate(-50%,15px);background:#11111c;border:1px solid rgba(98,232,221,.55);padding:10px 15px;color:var(--cyan);font:9px var(--mono);letter-spacing:.1em;opacity:0;pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:850px){.welcome-screen{gap:3%;padding:0 4%}.welcome-copy{width:41%}.welcome-copy h1{font-size:clamp(52px,8vw,76px)}.style-picker{width:54%;padding:19px}.style-card{padding:10px 8px}.combat-ui{width:92%;gap:24px}.fighter-card{width:250px}.game-screen{padding-left:4%;padding-right:4%}}
@media(max-width:620px){.app-shell{min-height:540px}.topbar{height:60px;padding:0 18px}.top-status{display:none}.screen{inset:60px 0 0}.scene-vignette{background:linear-gradient(90deg,rgba(8,8,15,.76),rgba(8,8,15,.35)),linear-gradient(0deg,rgba(8,8,15,.9),transparent 65%)}.welcome-screen{padding:18px 18px 56px;display:flex;flex-direction:column;justify-content:center;align-items:stretch;gap:18px;overflow:auto}.welcome-copy{width:100%;padding:0}.welcome-copy h1{font-size:55px}.intro{font-size:12px;margin:12px 0;max-width:340px}.career-note{display:none}.welcome-copy .eyebrow{font-size:8px;margin-bottom:9px}.style-picker{width:100%;margin:0;padding:16px}.picker-heading{margin-bottom:10px}.picker-heading h2{font-size:18px}.style-card{min-height:135px;padding:10px 8px}.style-name{font-size:12px}.style-desc{font-size:8px}.instrument-icon{font-size:23px;height:32px}.style-tag{font-size:7px;margin:3px 0 6px}.picker-foot{font-size:7px}.welcome-footer{left:18px;right:18px;bottom:12px;font-size:7px}.welcome-footer span:last-child{display:none}.corner-coordinate{display:none}.game-screen{padding:17px 16px 13px}.battle-head{gap:9px}.battle-title h2{font-size:20px}.battle-title .eyebrow{font-size:7px}.round-pill{padding:8px;font-size:7px}.icon-button{height:31px;padding:0 7px}.icon-button span{font-size:7px}.combat-ui{width:100%;gap:9px;margin:32px auto 0}.fighter-card{width:calc(50% - 13px);padding:10px 9px}.fighter-name{font-size:15px}.fighter-meta{font-size:7px}.fighter-level{font-size:6px}.fighter-badge{right:9px;top:31px;font-size:18px}.versus{font-size:10px}.rhythm-panel{width:100%;margin-top:25px;padding:12px}.battle-bottom{width:100%;grid-template-columns:.75fr 1.2fr .75fr;gap:9px;margin-top:18px}.attack-button{height:52px;gap:5px}.attack-key{font-size:7px;padding:3px}.attack-text{font-size:10px}.attack-arrow{display:none}.combo-box>b,.score-box>b{font-size:18px}.combo-label{font-size:7px}.combo-box small,.score-box small{font-size:6px}.game-footer{gap:11px;font-size:7px;padding-top:10px}.text-button{font-size:7px}.text-button span{display:none}.exit-button{display:none}.result-card,.garage-card{padding:25px}.garage-card h2{font-size:30px}}
@media(max-height:700px) and (min-width:621px){.welcome-copy h1{font-size:68px}.welcome-copy{padding-bottom:10px}.style-card{min-height:140px}.style-picker{padding:18px}.intro{margin:17px 0}.combat-ui{margin-top:18px}.rhythm-panel{margin-top:18px}.battle-bottom{margin-top:14px}}

import * as THREE from 'three';

const $ = (id) => document.getElementById(id);
const storageKey = 'ritmo-de-rua-save-v1';
const venues = [
  { name: 'BAIRRO DO CAIS', kicker: 'BAIRRO DO CAIS · DESAFIO 01', title: 'Ritmo de chegada', rival: 'DJ MARÉ', crew: 'CREW DO CAIS', hp: 100, reward: 80 },
  { name: 'PÁTIO 13', kicker: 'ESCOLA MUNICIPAL · DESAFIO 02', title: 'Batalha do intervalo', rival: 'LUNA LOOP', crew: 'CLUBE DO PÁTIO', hp: 135, reward: 125 },
  { name: 'GALPÃO 9', kicker: 'ZONA INDUSTRIAL · DESAFIO 03', title: 'Noite de amplificadores', rival: 'TONI RUÍDO', crew: 'OS SUBGRAVES', hp: 180, reward: 190 },
  { name: 'GRANDE AUDITÓRIO', kicker: 'SELETIVA PROFISSIONAL · FINAL', title: 'O palco é seu', rival: 'MAESTRO ZERO', crew: 'BANCA DE MESTRES', hp: 230, reward: 350 }
];
const instruments = {
  guitar: { label: 'GUITARRA', color: 0xff4e91, base: 22, special: 'POWER CHORD', badge: '〽' },
  flute: { label: 'FLAUTA', color: 0x62e8dd, base: 15, special: 'ECO MÁGICO', badge: '〰' },
  keys: { label: 'TECLAS', color: 0xf6cb74, base: 13, special: 'NOTAS EM CASCATA', badge: '▥' }
};
let save = loadSave();
let selectedStyle = save.style || 'guitar';
let scene, camera, renderer, clock, playerModel, rivalModel, particles = [], audioCtx = null;
let active = false, soundOn = true, startedAt = 0, lastBeat = -1, lastInput = 0, enemyBeat = 0;
let playerHP = 100, rivalHP = 100, combo = 0, score = 0, runDamage = 0, currentVenue = 0;
let toastTimer;

function loadSave() {
  try { return { style: 'guitar', cash: 120, level: 1, upgrade: 0, unlocked: 0, ...JSON.parse(localStorage.getItem(storageKey) || '{}') }; }
  catch { return { style: 'guitar', cash: 120, level: 1, upgrade: 0, unlocked: 0 }; }
}
function persist() { localStorage.setItem(storageKey, JSON.stringify(save)); }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

function initScene() {
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x10101a);
  scene.fog = new THREE.Fog(0x10101a, 18, 54);
  camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, .1, 100);
  camera.position.set(0, 7.1, 19.5);
  camera.lookAt(0, 2.4, -1.5);
  renderer = new THREE.WebGLRenderer({ canvas: $('world'), antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
  renderer.setSize(innerWidth, innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.15;
  clock = new THREE.Clock();
  scene.add(new THREE.HemisphereLight(0x9ca9d0, 0x17121c, 2.0));
  const keyLight = new THREE.DirectionalLight(0xffd5c0, 3.2);
  keyLight.position.set(-5, 10, 7); keyLight.castShadow = true; keyLight.shadow.mapSize.set(1024, 1024); scene.add(keyLight);
  const pinkLight = new THREE.PointLight(0xff3687, 45, 22); pinkLight.position.set(4, 5, -1); scene.add(pinkLight);
  const cyanLight = new THREE.PointLight(0x35dcd3, 35, 18); cyanLight.position.set(-5, 4, 2); scene.add(cyanLight);
  buildCity();
  playerModel = buildFighter(-2.2, 0x263e52, 0x62e8dd, false);
  rivalModel = buildFighter(2.2, 0x4b2339, 0xff4e91, true);
  scene.add(playerModel, rivalModel);
  window.addEventListener('resize', resizeScene);
  animate();
}
function material(color, roughness = .8, metalness = 0) { return new THREE.MeshStandardMaterial({ color, roughness, metalness }); }
function box(parent, size, pos, mat, cast = true) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(...size), mat);
  m.position.set(...pos); m.castShadow = cast; m.receiveShadow = true; parent.add(m); return m;
}
function cylinder(parent, rt, rb, h, pos, mat, radial = 10) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, radial), mat);
  m.position.set(...pos); m.castShadow = true; parent.add(m); return m;
}
function buildCity() {
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(90, 90), material(0x20202a, .94));
  ground.rotation.x = -Math.PI / 2; ground.position.y = -.08; ground.receiveShadow = true; scene.add(ground);
  // Wet pavement strips catch the neon reflections.
  for (let i = -5; i <= 5; i++) {
    const line = new THREE.Mesh(new THREE.BoxGeometry(.035, .012, 28), new THREE.MeshBasicMaterial({ color: i % 2 ? 0x362b3b : 0x243239, transparent: true, opacity: .8 }));
    line.position.set(i * 1.3, -.01, -1); scene.add(line);
  }
  const facadeColors = [0x242431, 0x302a37, 0x202c34, 0x35272f, 0x242938];
  for (let side of [-1, 1]) {
    for (let i = 0; i < 5; i++) {
      const x = side * (7.2 + i * 2.1), z = -4 - (i % 3) * 2;
      const w = 3.4 + (i % 2) * 1.4, h = 7 + (i % 3) * 2.5;
      const building = box(scene, [w, h, 5], [x, h / 2 - .1, z], material(facadeColors[(i + (side > 0 ? 2 : 0)) % facadeColors.length]), false);
      building.receiveShadow = true;
      for (let row = 0; row < 3; row++) for (let col = 0; col < 2; col++) {
        const lit = (row * 3 + col * 2 + i) % 4 === 1;
        const win = box(scene, [.5, .76, .04], [x - w * .26 + col * w * .48, 1.4 + row * 1.5, z + 2.53], new THREE.MeshBasicMaterial({ color: lit ? (i % 2 ? 0xffc875 : 0x67d9db) : 0x343546, transparent: true, opacity: lit ? .88 : .7 }), false);
      }
      if (i < 3) {
        const signColor = i % 2 ? 0x62e8dd : 0xff4e91;
