  playTone(440, .15, 'sine');
}
function nextChallenge() {
  $('result-modal').classList.add('hidden');
  if (save.unlocked >= venues.length) showVenue(0);
  else if (currentVenue < save.unlocked) showVenue(currentVenue + 1);
