window.addEventListener('keydown', (event) => {
  if (event.code === 'Space' && !event.repeat) { event.preventDefault(); pressAttack(); }
  if (event.key === 'Escape') {
    if (!$('garage-modal').classList.contains('hidden')) closeGarage();
