input.command:
node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(`PAGE ${e.message}`));
page.on('console', m => { if (m.type() === 'error') errors.push(`CONSOLE ${m.text()}`); });
page.on('response', r => { if (r.status() >= 400 && new URL(r.url()).origin === 'http://localhost:3002') errors.push(`HTTP ${r.status()} ${r.url()}`); });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.screenshot({ path: 'screenshots/welcome.jpg', type: 'jpeg', quality: 85 });
await page.click('#start-career');
await page.waitForSelector('#game-screen:not(.hidden)');
const rounds = [];
for (let round = 1; round <= 4; round++) {
  const start = Date.now();
  while (Date.now() - start < 20000 && await page.locator('#result-modal').evaluate(el => el.classList.contains('hidden'))) {
    await page.click('#attack-button');
    await page.waitForTimeout(360);
  }
  const result = await page.locator('#result-title').textContent();
  const hp = await page.locator('#player-hp-text').textContent();
  rounds.push({ round, result, hp });
  if (round === 1 && result.includes('Seu som')) {
    await page.click('#result-garage');
    await page.waitForSelector('#garage-modal:not(.hidden)');
    await page.click('#buy-upgrade');
    const garage = await page.locator('#garage-level').textContent();
    await page.click('#close-garage');
    rounds[0].garage = garage;
  }
  if (round < 4) {
    await page.click('#result-next');
    await page.waitForTimeout(100);
  }
}
await page.screenshot({ path: 'screenshots/battle.jpg', type: 'jpeg', quality: 85 });
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(250);
await page.screenshot({ path: 'screenshots/battle-mobile.jpg', type: 'jpeg', quality: 85 });
console.log(JSON.stringify({ rounds, cash: await page.locator('#cash').textContent(), errors }, null, 2));
await browser.close();
EOF

