import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });
await page.click('#start-career');
await page.waitForTimeout(500);
await page.screenshot({ path: 'screenshots/battle.jpg', type: 'jpeg', quality: 85 });
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(300);
await page.screenshot({ path: 'screenshots/battle-mobile.jpg', type: 'jpeg', quality: 85 });
const metrics = await page.evaluate(() => ({
  viewport: [innerWidth, innerHeight],
  bodyScroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
  gameRect: (() => { const r = document.querySelector('#game-screen').getBoundingClientRect(); return [Math.round(r.width), Math.round(r.height)]; })(),
  controls: [...document.querySelectorAll('.battle-head, .combat-ui, .rhythm-panel, .battle-bottom, .game-footer')].map(e => { const r=e.getBoundingClientRect(); return [e.className, Math.round(r.left), Math.round(r.top), Math.round(r.right), Math.round(r.bottom)]; })
}));
console.log(JSON.stringify({ metrics, errors }, null, 2));
await browser.close();
EOF

